def proj_hook(d):
    def h(mod,inp,out):
        o=out[0] if isinstance(out,tuple) else out
        p=o - (o@d).unsqueeze(-1)*d
        if isinstance(out,tuple): return (p,)+out[1:]
        return p
    return h

